select public.seed_wines('[{"s":"domaine-du-vieux-telegraphe-la-crau-blanc","n":"Châteauneuf-du-Pape La Crau Blanc","p":"Domaine du Vieux Télégraphe","t":"white","c":"France","r":"Southern Rhône","a":"Châteauneuf-du-Pape","g":["Clairette","Grenache Blanc","Roussanne","Bourboulenc"],"pr":75,"abv":13.5,"e":"Fermented in tank and foudre with a small barrel portion, about 8 months on lees","sv":"11–13°C","d":"30 minutes","w":"Now–5 years, or after 10 for honeyed secondary notes","ds":"White Châteauneuf from the galet-strewn La Crau plateau: pear, quince and white peach with fennel, chamomile and a garrigue lift. Broad and waxy in the southern way, but Clairette and Bourboulenc add a saline, almond-skin finish that keeps it fresh.","x":"284:3,285:42,286:4,287:60,288:75,289:65,290:70,291:15,292:0,293:15,49:55,51:40,54:45,55:25,40:25,85:50,74:35,79:30,100:35,127:25,106:25,202:40,193:25,141:35,136:35,222:55,224:55,223:35,250:50,242:40,236:45,260:40,266:30,279:55,282:50,303:100,305:100,298:100,314:100"},{"s":"domaine-du-cayron-gigondas","n":"Gigondas","p":"Domaine du Cayron","t":"red","c":"France","r":"Southern Rhône","a":"Gigondas","g":["Grenache","Syrah","Cinsault","Mourvèdre"],"pr":40,"abv":15,"e":"Fermented in concrete, aged in old oak foudres; bottled unfined and unfiltered","sv":"16–18°C","d":"1 hour","w":"3–15 years from vintage","ds":"Traditional, unpolished Gigondas from the foot of the Dentelles de Montmirail: warm kirsch and raspberry under a thick layer of garrigue, dusty earth and a little leather. Generous alcohol and rustic, grippy tannin give it a rugged build that suits a slow braise.","x":"284:3,285:50,286:70,287:80,288:80,289:75,290:70,291:10,292:0,293:20,27:70,1:35,3:30,14:45,12:35,106:80,102:30,78:20,120:35,126:30,153:40,185:30,143:25,152:20,218:50,216:45,227:40,246:65,242:60,237:60,241:55,258:70,260:70,278:35,265:30,282:65,279:45,295:100,297:100,300:100,315:100"},{"s":"e-guigal-cotes-du-rhone-rouge","n":"Côtes du Rhône Rouge","p":"E. Guigal","t":"red","c":"France","r":"Southern Rhône","a":"Côtes du Rhône","g":["Syrah","Grenache","Mourvèdre"],"pr":15,"abv":14,"e":"About 18 months in large oak foudres","sv":"15–17°C","d":"Not needed","w":"Now–5 years","ds":"One of France''s most dependable everyday reds, and unusually Syrah-led for a Côtes du Rhône. Black cherry and blackberry with a peppery edge, a brush of garrigue and olive, and soft, rounded tannins. It drinks well on release and is an easy match for a wide range of food.","x":"284:4,285:50,286:50,287:65,288:60,289:60,290:50,291:15,292:0,293:20,14:55,12:55,3:30,15:35,27:30,120:50,106:45,112:25,126:20,71:20,190:15,153:20,231:55,229:45,224:40,256:80,244:55,250:50,258:55,260:45,283:80,279:50,302:100,300:100,311:100,301:100"},{"s":"chateau-d-aqueria-tavel","n":"Tavel Rosé","p":"Château d''Aqueria","t":"rose","c":"France","r":"Southern Rhône","a":"Tavel","g":["Grenache","Cinsault","Clairette","Mourvèdre","Syrah","Bourboulenc"],"pr":24,"abv":14,"e":"Short skin maceration, fermented and aged in temperature-controlled tank","sv":"10–12°C","d":"Not needed","w":"Now–3 years","ds":"Tavel is rosé built like a light red, and Aqueria is a textbook example: deep pink, with strawberry, raspberry and pomegranate, a hint of blood orange and southern herbs. A touch of skin grip and real weight make it a rosé for the dinner table, not just the terrace.","x":"284:4,285:50,286:10,287:65,288:60,289:65,290:55,291:0,292:0,293:10,4:60,3:55,1:50,11:20,8:30,6:30,38:25,72:30,106:30,121:20,136:20,232:45,224:45,229:50,250:55,242:40,241:40,258:70,261:70,279:75,283:70,301:100,298:100,308:100,304:100,296:100"},{"s":"chateau-d-esclans-whispering-angel","n":"Whispering Angel","p":"Château d''Esclans","t":"rose","c":"France","r":"Provence","a":"Côtes de Provence","g":["Grenache","Cinsault","Rolle"],"pr":22,"abv":13,"e":"Direct press and stainless steel fermentation","sv":"8–10°C","d":"Not needed","w":"Now–2 years","ds":"The pale, onion-skin Provence rosé that set the style for a generation. Light strawberry, watermelon and white peach with a squeeze of grapefruit and a saline finish. Crisp and polished, it is built for refreshment rather than complexity.","x":"284:4,285:55,286:2,287:50,288:35,289:45,290:45,291:0,292:0,293:5,4:45,5:20,6:30,11:45,53:45,36:35,40:25,65:30,85:30,72:20,106:15,141:25,136:20,228:60,225:35,240:85,256:90,236:40,247:55,261:80,279:85,283:90,323:100,305:100,313:100,303:100"},{"s":"domaine-tempier-bandol-rouge","n":"Bandol Rouge","p":"Domaine Tempier","t":"red","c":"France","r":"Provence","a":"Bandol","g":["Mourvèdre","Grenache","Cinsault","Carignan"],"pr":60,"abv":14,"e":"18–20 months in large old oak foudres","sv":"16–18°C","d":"1–2 hours","w":"8–25 years from vintage","ds":"Mourvèdre on the limestone terraces above the Mediterranean: blackberry and plum under a deep layer of garrigue, black olive, licorice and gamey leather. The tannins are firm and dusty when young, and in the bottle it develops toward earth, truffle and dried herbs.","x":"284:2,285:60,286:80,287:65,288:80,289:75,290:80,291:10,292:0,293:20,12:60,15:45,14:40,17:30,106:70,102:35,105:25,112:60,126:40,185:50,188:45,190:25,143:30,151:35,170:20,216:70,217:40,227:50,242:85,245:85,246:45,251:55,258:90,260:75,282:90,279:50,295:100,297:100,300:100,294:100"},{"s":"chateau-de-l-hortus-bergerie-de-l-hortus-pic-saint-loup","n":"Bergerie de l''Hortus Pic Saint-Loup","p":"Château de l''Hortus","t":"red","c":"France","r":"Languedoc-Roussillon","a":"Pic Saint-Loup","g":["Syrah","Grenache","Mourvèdre"],"pr":20,"abv":13.5,"e":"Fermented and aged in tank, bottled young","sv":"15–17°C","d":"Not needed","w":"Now–5 years","ds":"The early-drinking cuvée from the estate that put Pic Saint-Loup on the map. Bright blackberry and black cherry soaked in wild thyme and rosemary, with a pinch of pepper and olive. It has the freshness of the appellation''s cooler, higher sites and only light tannin.","x":"284:3,285:55,286:50,287:60,288:60,289:60,290:55,291:5,292:0,293:10,12:55,14:50,3:30,15:30,106:75,102:35,103:20,120:45,112:30,126:20,71:20,140:20,229:55,231:45,214:30,240:60,242:55,256:75,244:45,261:55,279:80,283:75,295:100,300:100,301:100,311:100"},{"s":"chateau-sainte-eulalie-la-cantilene-minervois-la-liviniere","n":"La Cantilène Minervois La Livinière","p":"Château Sainte Eulalie","t":"red","c":"France","r":"Languedoc-Roussillon","a":"Minervois La Livinière","g":["Syrah","Grenache","Carignan"],"pr":22,"abv":14,"e":"About 12 months in oak barrels, partly new","sv":"16–18°C","d":"30 minutes","w":"2–10 years from vintage","ds":"A fuller, barrel-aged Minervois from the La Livinière cru: ripe blackberry and plum with garrigue, licorice and black pepper, plus some vanilla, toast and cocoa from the oak. Old-vine Carignan gives it depth, and the velvety texture delivers a lot of wine for the money.","x":"284:3,285:50,286:65,287:65,288:75,289:70,290:65,291:45,292:0,293:20,12:70,15:50,14:40,16:20,106:60,102:25,120:40,126:40,112:30,156:30,157:30,170:30,158:20,153:25,143:15,213:50,216:30,226:45,241:60,250:55,255:50,247:45,259:35,278:30,279:55,280:30,300:100,295:100,294:100,315:100"},{"s":"les-clos-de-paulilles-banyuls-rimage","n":"Banyuls Rimage","p":"Les Clos de Paulilles","t":"fortified","c":"France","r":"Languedoc-Roussillon","a":"Banyuls","g":["Grenache Noir"],"pr":28,"abv":16,"e":"Mutage on the skins, then a short, protected ageing before early bottling to keep the fruit","sv":"14–16°C","d":"Not needed","w":"Now–15 years","ds":"Vintage-style Banyuls, bottled young to keep its fruit, from the schist terraces above the Côte Vermeille. Kirsch, black cherry and fig with dark chocolate and cocoa, and a sweet, velvety texture that is less heavy than Port. One of the few wines that can match a chocolate dessert.","x":"284:70,285:50,286:50,287:80,288:80,289:80,290:75,291:5,292:0,293:15,27:75,14:70,12:50,3:30,23:30,22:30,28:40,168:55,170:45,126:30,135:25,106:20,226:65,213:50,224:50,257:60,244:65,241:70,250:55,275:95,268:25,279:70,282:55,321:100,317:100,322:100,320:100"},{"s":"trimbach-riesling-clos-sainte-hune","n":"Riesling Clos Sainte Hune","p":"Trimbach","t":"white","c":"France","r":"Alsace","a":"Alsace (Rosacker, Hunawihr)","g":["Riesling"],"pr":300,"abv":13,"e":"Fermented and aged in stainless steel and old foudres; held several years in bottle before release","sv":"10–12°C","d":"1 hour when young","w":"10–30+ years from vintage","ds":"A tiny walled parcel in the Rosacker grand cru that yields France''s most celebrated dry Riesling. Lime, lemon zest and white peach over wet limestone and saline, flinty minerality, with petrol and linden appearing as it ages. It is austere, very precise and extremely long, and needs a decade to show its best.","x":"284:3,285:90,286:2,287:50,288:55,289:80,290:95,291:2,292:0,293:35,35:65,40:55,36:30,46:40,53:45,55:20,85:40,86:30,79:20,136:75,138:40,137:30,141:45,191:35,192:15,193:15,230:80,225:55,228:50,239:60,249:95,243:95,248:80,258:90,236:75,261:55,260:25,282:100,280:45,303:100,305:100,306:100,296:100"},{"s":"zind-humbrecht-pinot-gris-rangen-de-thann-clos-saint-urbain","n":"Pinot Gris Rangen de Thann Clos Saint Urbain Grand Cru","p":"Domaine Zind-Humbrecht","t":"white","c":"France","r":"Alsace","a":"Alsace Grand Cru Rangen","g":["Pinot Gris"],"pr":120,"abv":14,"e":"Slow native-yeast fermentation and long lees ageing in old foudres","sv":"11–13°C","d":"1 hour","w":"5–25 years from vintage","ds":"Pinot Gris from the steep volcanic slope of the Rangen, Alsace''s southernmost grand cru, with a smoky character that comes from the soil, not the barrel. Smoke and struck flint run through ripe pear, quince, mirabelle and honey, with a gingery bite. The texture is dense and oily, and a little residual sugar is absorbed by the extract.","x":"284:25,285:55,286:5,287:70,288:85,289:85,290:90,291:5,292:0,293:20,158:80,137:55,146:70,147:25,54:40,49:50,51:40,55:35,57:30,192:45,209:15,129:25,121:15,149:15,223:70,222:40,221:30,224:45,237:70,238:60,243:80,248:80,255:75,260:55,266:40,265:20,282:90,279:45,299:100,296:100,322:100,310:100,315:100"},{"s":"lucien-albrecht-cremant-d-alsace-brut-rose","n":"Crémant d''Alsace Brut Rosé","p":"Lucien Albrecht","t":"sparkling","c":"France","r":"Alsace","a":"Crémant d''Alsace","g":["Pinot Noir"],"pr":22,"abv":12,"e":"Traditional method, around 14 months on lees","sv":"6–8°C","d":"Not needed","w":"Now–3 years","ds":"All-Pinot Noir traditional-method rosé with bright strawberry, wild raspberry and red cherry, a squeeze of lemon and a light brioche note from lees ageing. The mousse is lively and the finish crisp and dry, so it does much of what rosé Champagne does at a fraction of the price.","x":"284:7,285:75,286:3,287:40,288:35,289:50,290:50,291:0,292:95,293:15,4:60,5:35,1:45,3:40,6:35,40:30,85:20,136:20,178:25,179:20,180:15,228:70,233:55,234:30,240:90,256:80,236:40,244:50,272:90,261:40,279:80,283:85,323:100,301:100,319:100,304:100"},{"s":"trimbach-gewurztraminer-vendanges-tardives","n":"Gewurztraminer Vendanges Tardives","p":"Trimbach","t":"dessert","c":"France","r":"Alsace","a":"Alsace Vendanges Tardives","g":["Gewurztraminer"],"pr":85,"abv":13.5,"e":"Late-harvested, overripe grapes fermented slowly and aged in stainless steel and old foudres","sv":"8–10°C","d":"Not needed","w":"5–25 years from vintage","ds":"Late-harvest Gewurztraminer with the variety''s perfume pushed to the limit: lychee, rose petal and jasmine, then candied orange peel, honey and ginger. Rich and oily, but Trimbach''s house restraint keeps the sweetness in check, so it finishes spicy rather than sugary.","x":"284:65,285:50,286:3,287:55,288:85,289:90,290:85,291:2,292:0,293:20,61:95,72:85,59:30,58:20,55:30,31:40,39:35,210:25,192:55,209:25,129:55,123:20,124:15,132:15,77:30,75:30,223:70,226:55,224:50,252:100,238:80,257:75,255:70,270:95,269:20,261:40,282:80,279:45,322:100,317:100,320:100,308:100"},{"s":"domaine-jean-macle-chateau-chalon","n":"Château-Chalon","p":"Domaine Jean Macle","t":"white","c":"France","r":"Jura","a":"Château-Chalon","g":["Savagnin"],"pr":110,"abv":14,"e":"Vin jaune: at least 6 years 3 months under a flor veil in old, unfilled barrels; bottled in 62 cl clavelin","sv":"14–16°C","d":"1–2 hours, or open the day before","w":"10–50+ years from vintage","ds":"Benchmark vin jaune from the cliff-top village of Château-Chalon, aged more than six years under flor without topping up. Fresh walnut, curry spice and green apple skin over a salty, mushroom-and-umami savouriness, with acidity sharp enough to cut. The finish is extraordinarily long, and an opened bottle keeps for weeks.","x":"284:2,285:78,286:5,287:65,288:70,289:90,290:100,291:20,292:0,293:75,204:90,207:90,211:75,203:50,202:35,46:30,40:30,51:20,141:60,136:30,149:35,196:50,129:20,132:25,193:25,192:10,230:60,225:35,223:25,239:50,242:95,248:95,243:50,258:95,267:100,260:80,282:100,281:60,315:100,298:100,310:100,312:100"},{"s":"stephane-tissot-arbois-trousseau-singulier","n":"Arbois Trousseau Singulier","p":"Domaine André et Mireille Tissot (Stéphane Tissot)","t":"red","c":"France","r":"Jura","a":"Arbois","g":["Trousseau"],"pr":45,"abv":12.5,"e":"Native-yeast fermentation, about 12 months in old foudres and barrels, minimal sulfur","sv":"14–16°C","d":"30 minutes","w":"Now–10 years","ds":"Biodynamic Trousseau that is pale in colour but full of flavour: sour cherry, raspberry and red currant with rose petal, white pepper and a forest-floor, slightly wild undertone. Light-bodied and taut, with fine tannin, it shows how much aromatic detail a red can carry at low weight.","x":"284:2,285:70,286:40,287:40,288:40,289:60,290:60,291:10,292:0,293:15,1:65,2:50,3:45,6:40,7:25,5:30,72:30,197:15,121:40,111:30,148:35,143:30,154:20,155:10,214:45,229:55,230:40,242:60,254:50,240:75,252:55,253:25,265:70,260:65,279:65,298:100,310:100,301:100,299:100"},{"s":"andre-et-michel-quenard-chignin-bergeron","n":"Chignin-Bergeron","p":"Domaine André et Michel Quenard","t":"white","c":"France","r":"Savoie","a":"Chignin-Bergeron","g":["Roussanne"],"pr":28,"abv":13,"e":"Fermented and aged in stainless steel on lees","sv":"10–12°C","d":"Not needed","w":"Now–6 years","ds":"Roussanne, called Bergeron here, from steep, stony Alpine slopes: apricot, quince and pear with honeysuckle and almond. The texture is waxy in the Rhône manner, but the mountain climate gives cooler, stonier lines and a fresher finish. A natural partner for Alpine cheese dishes.","x":"284:4,285:55,286:2,287:50,288:60,289:60,290:60,291:0,292:0,293:10,55:60,51:40,49:55,54:35,41:20,74:40,73:30,79:25,202:35,192:25,100:15,136:45,140:30,141:20,222:50,224:45,228:30,240:55,243:50,236:45,250:40,261:70,266:35,279:70,283:60,315:100,303:100,298:100,312:100"},{"s":"chateau-montus-madiran","n":"Château Montus Madiran","p":"Alain Brumont","t":"red","c":"France","r":"South West","a":"Madiran","g":["Tannat","Cabernet Sauvignon"],"pr":45,"abv":14.5,"e":"12–14 months in oak barriques, a large share new","sv":"17–18°C","d":"2–3 hours","w":"10–25 years from vintage","ds":"Brumont''s Montus is the wine that modernised Madiran: Tannat from galet-covered slopes, fully ripened and aged in new oak. Blackberry, black plum and licorice under espresso, cocoa and toast, with some of the firmest tannins in France. Built for duck confit and cassoulet, or for a long cellaring.","x":"284:2,285:62,286:95,287:70,288:90,289:85,290:85,291:70,292:0,293:20,12:75,15:60,13:50,14:30,23:15,126:50,168:45,170:40,166:30,156:40,157:50,158:30,142:40,143:25,198:30,185:20,216:80,220:40,227:60,237:90,245:90,255:80,251:70,247:40,259:70,282:95,279:65,299:100,294:100,297:100,295:100,315:100"},{"s":"vietti-moscato-d-asti-cascinetta","n":"Moscato d''Asti Cascinetta","p":"Vietti","t":"sparkling","c":"Italy","r":"Piedmont","a":"Moscato d''Asti DOCG","g":["Moscato Bianco"],"pr":17,"abv":5.5,"e":"Single fermentation in pressurized steel tank, arrested at ~5.5% to keep natural grape sugar","sv":"6–8°C","d":"Not needed","w":"Drink within 1–2 years of release","ds":"Fresh-crushed white grape, ripe peach and orange blossom in a gentle froth, with a sage-leaf lift that keeps it from cloying. Sweet, low in alcohol and gleaming with acidity, it tastes like biting into a chilled Muscat grape straight off the vine.","x":"284:60,285:62,286:0,287:5,288:25,289:70,290:50,291:0,292:35,293:10,70:90,52:85,53:60,55:55,41:40,49:35,40:30,75:80,74:50,73:30,104:25,192:15,129:10,235:75,229:60,240:85,252:85,256:90,261:70,274:50,279:90,283:90,320:100,323:100,308:100,316:100"},{"s":"pieropan-soave-classico","n":"Soave Classico","p":"Pieropan","t":"white","c":"Italy","r":"Veneto","a":"Soave Classico DOC","g":["Garganega","Trebbiano di Soave"],"pr":20,"abv":12,"e":"Stainless steel on fine lees for several months","sv":"8–10°C","d":"Not needed","w":"Now–5 years","ds":"The benchmark for what Soave can be: pear, white peach and lemon framed by Garganega''s signature bitter-almond finish. Volcanic hillside soils lend a smoky, stony cut that makes it far more serious than its price.","x":"284:3,285:65,286:2,287:40,288:40,289:55,290:55,291:0,292:0,293:15,202:70,49:60,53:55,34:50,47:35,45:20,100:15,85:60,73:40,79:30,146:45,136:50,141:30,228:55,224:35,240:80,236:60,243:55,258:75,261:75,266:30,279:70,283:70,303:100,305:100,313:100,312:100"},{"s":"nino-franco-rustico-prosecco-superiore","n":"Rustico Valdobbiadene Prosecco Superiore Brut","p":"Nino Franco","t":"sparkling","c":"Italy","r":"Veneto","a":"Conegliano Valdobbiadene Prosecco Superiore DOCG","g":["Glera"],"pr":20,"abv":11,"e":"Charmat secondary fermentation in pressurized tank","sv":"6–8°C","d":"Not needed","w":"Within 2 years of release","ds":"Hillside Prosecco with genuine poise: crisp pear, green apple and acacia blossom carried on a soft, lively froth. Drier and more focused than most, with a faint almond note on the finish.","x":"284:12,285:62,286:0,287:30,288:30,289:55,290:50,291:0,292:90,293:10,49:80,46:65,53:50,34:40,68:35,85:60,73:55,202:20,179:10,136:25,234:55,233:30,228:60,240:90,256:85,236:45,274:90,261:60,279:90,283:90,323:100,301:100,319:100,305:100"},{"s":"cleto-chiarli-vecchia-modena-premium-lambrusco-di-sorbara","n":"Vecchia Modena Premium Lambrusco di Sorbara","p":"Cleto Chiarli","t":"sparkling","c":"Italy","r":"Emilia-Romagna","a":"Lambrusco di Sorbara DOC","g":["Lambrusco di Sorbara"],"pr":18,"abv":11,"e":"Brief maceration for a pale, rosé-like color; Charmat secondary fermentation","sv":"8–10°C","d":"Not needed","w":"Within 1–2 years of release","ds":"Pale ruby and bone dry, all wild strawberry, red currant and violet with a frothy, mouth-watering snap. Sorbara is the lightest and most acid-driven of the Lambruscos, built to slice through Modena''s salumi and fried gnocco.","x":"284:6,285:85,286:12,287:30,288:25,289:60,290:45,291:0,292:80,293:10,5:80,3:65,6:55,7:50,8:35,11:25,10:20,38:20,71:45,72:30,140:15,234:65,228:70,229:65,225:40,240:95,244:60,256:90,274:85,279:90,283:90,301:100,311:100,319:100,296:100"},{"s":"masciarelli-montepulciano-d-abruzzo","n":"Montepulciano d''Abruzzo","p":"Masciarelli","t":"red","c":"Italy","r":"Abruzzo","a":"Montepulciano d''Abruzzo DOC","g":["Montepulciano"],"pr":13,"abv":13.5,"e":"Stainless steel, short rest before bottling","sv":"15–17°C","d":"Not needed","w":"Now–4 years","ds":"Generous, dark and honest: black cherry and plum with a dusting of dried oregano, licorice and earth. Soft-edged but with a rustic tannic tug that begs for pizza or a grilled sausage.","x":"284:3,285:55,286:55,287:55,288:60,289:60,290:50,291:5,292:0,293:15,14:80,15:65,12:50,2:35,71:30,126:35,111:30,107:20,120:20,153:30,151:20,170:15,218:40,217:40,229:50,246:50,256:75,244:55,242:35,261:60,279:70,283:80,311:100,302:100,300:100,301:100"},{"s":"donnafugata-sherazade-nero-d-avola","n":"Sherazade Nero d''Avola","p":"Donnafugata","t":"red","c":"Italy","r":"Sicily","a":"Sicilia DOC","g":["Nero d''Avola"],"pr":22,"abv":13,"e":"Stainless steel, then a few months in bottle","sv":"14–16°C","d":"Not needed","w":"Now–3 years","ds":"Nero d''Avola in its sunniest, most succulent mode: red cherry, plum and mulberry with a pinch of black pepper and Sicilian scrub. Unoaked and supple, it can take a light chill on a warm evening.","x":"284:3,285:55,286:40,287:50,288:50,289:60,290:50,291:0,292:0,293:10,1:70,9:60,14:55,17:40,3:30,120:35,126:25,106:30,111:20,71:20,118:15,231:60,229:70,212:35,240:60,244:80,256:90,241:40,261:75,279:85,283:90,311:100,304:100,296:100,301:100"},{"s":"zenato-ripassa-valpolicella-ripasso-superiore","n":"Ripassa Valpolicella Ripasso Superiore","p":"Zenato","t":"red","c":"Italy","r":"Veneto","a":"Valpolicella Ripasso Superiore DOC","g":["Corvina","Rondinella","Croatina"],"pr":26,"abv":14,"e":"Refermented on Amarone pomace, then about 18 months in large Slavonian oak casks","sv":"16–18°C","d":"30 minutes","w":"Now–8 years","ds":"A ''baby Amarone'' with real substance: black and dried cherry, a whisper of raisin and cocoa, warm cinnamon spice. Passing the wine over Amarone skins adds plushness and depth while Corvina''s sour-cherry snap keeps it lively.","x":"284:6,285:58,286:55,287:70,288:70,289:70,290:65,291:35,292:0,293:25,14:75,26:60,2:40,9:40,27:35,24:35,23:25,124:30,123:20,156:20,170:35,186:25,199:15,111:15,213:50,224:55,226:40,250:65,241:60,256:60,271:60,260:55,280:40,283:60,294:100,315:100,310:100,314:100"},{"s":"tormaresca-torcicoda-primitivo","n":"Torcicoda Primitivo","p":"Tormaresca","t":"red","c":"Italy","r":"Puglia","a":"Salento IGT","g":["Primitivo"],"pr":22,"abv":14.5,"e":"About 10 months in French and Hungarian oak barriques","sv":"16–18°C","d":"30 minutes, optional","w":"Now–6 years","ds":"Southern sunshine in a glass: jammy black plum and blackberry layered with mocha, vanilla and licorice. Plush and full, with just enough peppery lift and tannin to stand up to anything off the grill.","x":"284:6,285:45,286:50,287:78,288:80,289:78,290:62,291:45,292:0,293:18,15:75,12:70,28:55,14:50,23:35,22:25,167:35,156:40,170:30,126:35,120:30,135:30,106:15,152:15,213:55,226:60,224:50,241:85,250:75,244:80,257:45,256:60,259:35,279:60,300:100,302:100,294:100,315:100"},{"s":"tenuta-delle-terre-nere-etna-rosso","n":"Etna Rosso","p":"Tenuta delle Terre Nere","t":"red","c":"Italy","r":"Sicily","a":"Etna DOC","g":["Nerello Mascalese","Nerello Cappuccio"],"pr":28,"abv":13.5,"e":"About 12 months, mostly in used French tonneaux","sv":"15–17°C","d":"30 minutes","w":"Now–8 years","ds":"Red cherry, wild strawberry and rose petal over a smoky, ashen volcanic core. Nerello Mascalese gives Burgundian lightness with Nebbiolo-like grip, and the black lava soils of the volcano''s north face ring through every sip.","x":"284:2,285:75,286:58,287:55,288:50,289:65,290:65,291:20,292:0,293:20,1:75,2:55,5:50,6:35,39:15,72:40,71:25,111:35,121:25,114:20,146:80,158:30,143:25,140:40,214:55,217:30,230:45,240:75,236:70,243:85,242:50,260:45,279:60,282:45,311:100,310:100,304:100,296:100,301:100"},{"s":"braida-bricco-dell-uccellone-barbera-d-asti","n":"Bricco dell''Uccellone Barbera d''Asti","p":"Braida","t":"red","c":"Italy","r":"Piedmont","a":"Barbera d''Asti DOCG","g":["Barbera"],"pr":70,"abv":15,"e":"About 15 months in French oak barriques, a portion new, then a year in bottle","sv":"16–18°C","d":"1 hour","w":"3–15 years from vintage","ds":"The wine that proved Barbera could be grand: dense black cherry and plum wrapped in toast, mocha and licorice. Barbera''s naturally soaring acidity keeps the richness buoyant, and the barrique softens its low tannin into a polished, velvety frame.","x":"284:4,285:80,286:45,287:80,288:78,289:82,290:75,291:60,292:0,293:22,14:85,2:60,15:55,12:45,27:30,71:25,156:45,157:40,167:40,170:35,126:30,123:20,199:15,151:15,219:50,213:40,229:65,226:45,255:70,247:70,237:50,241:55,259:65,282:65,279:55,294:100,311:100,315:100,297:100"},{"s":"produttori-del-barbaresco-barbaresco","n":"Barbaresco","p":"Produttori del Barbaresco","t":"red","c":"Italy","r":"Piedmont","a":"Barbaresco DOCG","g":["Nebbiolo"],"pr":45,"abv":14,"e":"About 24 months in large Slavonian oak botti","sv":"16–18°C","d":"1–2 hours","w":"5–20 years from vintage","ds":"Textbook Nebbiolo from 